drop policy if exists "approved courses are public" on public.sahan_courses;drop policy if exists "instructors view own courses" on public.sahan_courses;drop policy if exists "instructors update own courses" on public.sahan_courses;drop policy if exists "instructors can view own row" on public.instructors;drop policy if exists "instructors can update own row" on public.instructors;drop policy if exists "admins manage instructors" on public.instructors;drop policy if exists "instructors manage own promotion requests" on public.promotion_requests;drop policy if exists "instructors view own promotions" on public.promotions;drop policy if exists "admins manage promotions" on public.promotions;drop policy if exists "admins manage rank overrides" on public.rank_overrides;drop policy if exists "instructors view own payouts" on public.payouts;drop policy if exists "admins manage payouts" on public.payouts;drop policy if exists "admins view self" on public.admins;
create policy "courses visible to public or owner admin" on public.sahan_courses for select to public using((admin_approved=true and status='published') or instructor_id in(select id from public.instructors where auth_user_id=auth.uid()) or public.is_sahan_admin());
create policy "course owners or admins can update" on public.sahan_courses for update to authenticated using(instructor_id in(select id from public.instructors where auth_user_id=auth.uid()) or public.is_sahan_admin()) with check(instructor_id in(select id from public.instructors where auth_user_id=auth.uid()) or public.is_sahan_admin());
create policy "instructor self or admin select" on public.instructors for select to authenticated using(auth_user_id=auth.uid() or public.is_sahan_admin());
create policy "instructor self or admin update" on public.instructors for update to authenticated using(auth_user_id=auth.uid() or public.is_sahan_admin()) with check(auth_user_id=auth.uid() or public.is_sahan_admin());
create policy "admins insert instructors" on public.instructors for insert to authenticated with check(public.is_sahan_admin());
create policy "admins delete instructors" on public.instructors for delete to authenticated using(public.is_sahan_admin());
create policy "instructors own promotion requests or admins" on public.promotion_requests for all to authenticated using(instructor_id in(select id from public.instructors where auth_user_id=auth.uid()) or public.is_sahan_admin()) with check(instructor_id in(select id from public.instructors where auth_user_id=auth.uid()) or public.is_sahan_admin());
create policy "promotion visibility for owner or admin" on public.promotions for select to authenticated using(course_id in(select id from public.sahan_courses where instructor_id in(select id from public.instructors where auth_user_id=auth.uid())) or public.is_sahan_admin());
create policy "admins insert promotions" on public.promotions for insert to authenticated with check(public.is_sahan_admin());
create policy "admins update promotions" on public.promotions for update to authenticated using(public.is_sahan_admin()) with check(public.is_sahan_admin());
create policy "admins delete promotions" on public.promotions for delete to authenticated using(public.is_sahan_admin());
create policy "admins manage rank overrides" on public.rank_overrides for all to authenticated using(public.is_sahan_admin()) with check(public.is_sahan_admin());
create policy "payouts visible to owner or admin" on public.payouts for select to authenticated using(instructor_id in(select id from public.instructors where auth_user_id=auth.uid()) or public.is_sahan_admin());
create policy "admins insert payouts" on public.payouts for insert to authenticated with check(public.is_sahan_admin());
create policy "admins update payouts" on public.payouts for update to authenticated using(public.is_sahan_admin()) with check(public.is_sahan_admin());
create policy "admins delete payouts" on public.payouts for delete to authenticated using(public.is_sahan_admin());
create policy "admins self or admin view" on public.admins for select to authenticated using(auth_user_id=auth.uid() or public.is_sahan_admin());
